/*
 * Release signing and versioning for the native customer app (lk.blynk.customer).
 * android/ is generated by `expo prebuild`, so this config plugin patches the generated
 * android/app/build.gradle (the same rules as apps/operations and apps/rider):
 *  - the release key and passwords live OUTSIDE the repo in ~/.blynk-release/keystore.properties
 *    (or the file named by BLYNK_KEYSTORE_PROPERTIES); without that file a release build is signed
 *    with the debug key, so a local test build still works but is not uploadable;
 *  - BLYNK_VERSION_CODE / BLYNK_VERSION_NAME override android.versionCode / expo.version at build
 *    time (every Play upload needs a higher versionCode).
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARK = '// blynk-release-signing';

const SIGNING = `
${MARK}
def blynkKeystorePropsFile = file(System.getenv('BLYNK_KEYSTORE_PROPERTIES') ?: "\${System.getProperty('user.home')}/.blynk-release/keystore.properties")
def blynkKeystoreProps = new Properties()
if (blynkKeystorePropsFile.exists()) {
    blynkKeystorePropsFile.withInputStream { blynkKeystoreProps.load(it) }
}
`;

module.exports = function withBlynkRelease(config) {
  return withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;
    if (src.includes(MARK)) return cfg;

    // 1. keystore properties, read before the android block
    src = src.replace(/\nandroid \{/, `${SIGNING}\nandroid {`);

    // 2. versionCode / versionName from the environment when set
    src = src.replace(
      /versionCode (\d+)/,
      `versionCode (System.getenv('BLYNK_VERSION_CODE')?.trim() ? System.getenv('BLYNK_VERSION_CODE').trim().toInteger() : $1)`
    );
    src = src.replace(
      /versionName "([^"]+)"/,
      `versionName (System.getenv('BLYNK_VERSION_NAME')?.trim() ?: "$1")`
    );

    // 3. a release signing config next to the debug one
    src = src.replace(
      /signingConfigs \{/,
      `signingConfigs {
        if (blynkKeystorePropsFile.exists()) {
            release {
                storeFile file(blynkKeystoreProps['storeFile'])
                storePassword blynkKeystoreProps['storePassword']
                keyAlias blynkKeystoreProps['keyAlias']
                keyPassword blynkKeystoreProps['keyPassword']
            }
        }`
    );

    // 4. the release build type uses it (the template points it at the debug key)
    src = src.replace(
      /(buildTypes \{[\s\S]*?release \{[\s\S]*?)signingConfig signingConfigs\.debug/,
      `$1signingConfig (blynkKeystorePropsFile.exists() ? signingConfigs.release : signingConfigs.debug)`
    );

    cfg.modResults.contents = src;
    return cfg;
  });
};
